/**
 * Example using acme-retry to retry a flaky function 5 times.
 * The flaky function simulates random failure with 70% success rate.
 */
const { retry } = require('./node_modules/acme-retry');

async function flakyOperation() {
  // 30% chance of failure
  if (Math.random() < 0.3) {
    throw new Error('Temporary failure — try again');
  }
  console.log('Operation succeeded!');
  return 'success';
}

async function main() {
  console.log('Attempting flaky operation with retry...');

  try {
    const result = await retry(flakyOperation, {
      attempts: 5,    // Try up to 5 times total
      baseMs: 200     // Start waiting 200ms, then double each try
    });
    console.log('Final result:', result);
  } catch (e) {
    console.error('All retry attempts failed:', e.message);
  }
}

main().catch(console.error);
